//! Small, dependency-free building blocks for writing cross-platform libraries.
//!
//! Every `#[cfg(...)]` attribute in this crate lives inside the [`platform`]
//! module. The public API is identical on all targets, so downstream crates
//! never need to write their own conditional-compilation blocks.
//!
//! # Example
//!
//! ```
//! use platform_kit::{current, Family};
//!
//! let platform = current();
//! match platform.family {
//!     Family::Unix => assert_eq!(platform.path_separator, '/'),
//!     Family::Windows => assert_eq!(platform.path_separator, '\\'),
//!     _ => {}
//! }
//! ```

#![forbid(unsafe_code)]

mod platform;

pub use platform::{current, Family, Platform};

//! The single home for target detection in this crate.
//!
//! `current()` is re-exported from whichever platform module matches the
//! build target, so callers see one stable function regardless of `cfg`.

mod info;

pub use info::{Family, Platform};

#[cfg(target_family = "unix")]
mod unix;
#[cfg(target_family = "unix")]
pub use unix::current;

#[cfg(target_family = "windows")]
mod windows;
#[cfg(target_family = "windows")]
pub use windows::current;

#[cfg(target_family = "wasm")]
mod wasm;
#[cfg(target_family = "wasm")]
pub use wasm::current;

#[cfg(not(any(
    target_family = "unix",
    target_family = "windows",
    target_family = "wasm",
)))]
mod fallback;
#[cfg(not(any(
    target_family = "unix",
    target_family = "windows",
    target_family = "wasm",
)))]
pub use fallback::current;

/// Broad classification of the current build target.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum Family {
    /// Unix-like targets such as Linux, macOS, and the BSDs.
    Unix,
    /// Microsoft Windows targets.
    Windows,
    /// WebAssembly targets, including WASI.
    Wasm,
    /// Any target not covered by the variants above.
    Other,
}

/// A description of the platform this crate was compiled for.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub struct Platform {
    /// The target family this description was produced for.
    pub family: Family,
    /// The `target_os` name reported by the toolchain.
    pub os: &'static str,
    /// The character separating components in a path.
    pub path_separator: char,
    /// The sequence that terminates a line in this platform's convention.
    pub line_ending: &'static str,
}

use super::{Family, Platform};

/// Returns a description of the current Unix-like platform.
#[must_use]
pub const fn current() -> Platform {
    Platform {
        family: Family::Unix,
        os: std::env::consts::OS,
        path_separator: '/',
        line_ending: "\n",
    }
}

use super::{Family, Platform};

/// Returns a description of the current Windows platform.
#[must_use]
pub const fn current() -> Platform {
    Platform {
        family: Family::Windows,
        os: std::env::consts::OS,
        path_separator: '\\',
        line_ending: "\r\n",
    }
}

use super::{Family, Platform};

/// Returns a description of the current WebAssembly platform.
#[must_use]
pub const fn current() -> Platform {
    Platform {
        family: Family::Wasm,
        os: std::env::consts::OS,
        path_separator: '/',
        line_ending: "\n",
    }
}

use super::{Family, Platform};

/// Returns a description of a target with no dedicated platform module.
#[must_use]
pub const fn current() -> Platform {
    Platform {
        family: Family::Other,
        os: std::env::consts::OS,
        path_separator: '/',
        line_ending: "\n",
    }
}

